// Valores iniciais (rodam uma vez ao fazer o deploy)
flow.set('cenario', 'B');          // B = com automação
flow.set('limiarOn', 150);         // lux: abaixo disso LIGA
flow.set('limiarOff', 200);        // lux: acima disso DESLIGA
flow.set('nuvensAlto', 70);        // % de nuvens considerado "céu fechado"
flow.set('acrescimoNuvens', 50);   // lux somados aos limiares em dia nublado
flow.set('amostrasConfirma', 2);   // amostras consecutivas para confirmar mudança
flow.set('nuvens', 0);
flow.set('potencia', 0);
flow.set('estadoReal', 'DESLIGADO');
flow.set('estadoCmd', '');
flow.set('pend', 0);
node.status({text:'init ok'});
return null;

// Troca de cenário: A = sem automação (referência) | B = com automação
const novo = msg.payload;
flow.set('cenario', novo);
flow.set('pend', 0);
flow.set('estadoCmd', '');
node.status({ text: 'cenario ' + novo });
if (novo === 'A') return { payload: 'LIGAR' };   // garante luminária ligada no cenário A
return null;

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch(e) { return null; } }
const w = Number(p.potencia_W);
if (!isFinite(w) || w < 0 || w > 1000) return null;
flow.set('potencia', w);
node.status({ text: w.toFixed(1) + ' W' });
return null;

const s = String(msg.payload).trim().toUpperCase();
if (s === 'LIGADO' || s === 'DESLIGADO') {
  flow.set('estadoReal', s);
  node.status({ text: s });
}
return null;

// REGRAS 1 e 2: histerese + ajuste de limiar pelo clima
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch(e) { return null; } }
const lux = Number(p.luminosidade);
// descarta leituras fora da faixa válida do sensor
if (!isFinite(lux) || lux < 0 || lux > 100000) { node.warn('Leitura descartada: ' + p.luminosidade); return null; }

const cenario   = flow.get('cenario') || 'B';
const nuvens    = Number(flow.get('nuvens') || 0);
const potMed    = Number(flow.get('potencia') || 0);
const estadoReal= flow.get('estadoReal') || 'DESLIGADO';
let   estadoCmd = flow.get('estadoCmd') || '';
const acr       = nuvens > flow.get('nuvensAlto') ? flow.get('acrescimoNuvens') : 0;   // REGRA 2
const limOn     = flow.get('limiarOn')  + acr;
const limOff    = flow.get('limiarOff') + acr;
const N         = flow.get('amostrasConfirma');

let desejado = estadoCmd || 'DESLIGADO';
if (cenario === 'A') {
  desejado = 'LIGADO';                         // cenário A: sem automação, luminária sempre ligada
} else {
  if (lux < limOn) desejado = 'LIGADO';        // REGRA 1: abaixo do limiar de acionamento
  else if (lux > limOff) desejado = 'DESLIGADO'; // acima do limiar de desligamento
}

// confirmação por N amostras consecutivas (evita acionar por pico isolado)
let cmdMsg = null;
if (desejado !== estadoCmd) {
  let pend = (flow.get('pend') || 0) + 1;
  if (pend >= N || cenario === 'A' || estadoCmd === '') {
    estadoCmd = desejado;
    flow.set('estadoCmd', estadoCmd);
    flow.set('pend', 0);
    cmdMsg = { payload: desejado === 'LIGADO' ? 'LIGAR' : 'DESLIGAR' };   // só envia quando o estado muda
  } else {
    flow.set('pend', pend);
  }
} else {
  flow.set('pend', 0);
}

// REGRA 3: potência efetiva (base do cálculo de energia)
// A: luminária sempre ligada -> potência medida. B: só conta quando o relé está ligado.
const potEfetiva = (cenario === 'A') ? potMed : (estadoReal === 'LIGADO' ? potMed : 0);

const fields = {
  luminosidade: lux,
  potencia_medida_W: potMed,
  potencia_efetiva_W: potEfetiva,
  estado_cmd: estadoCmd === 'LIGADO' ? 1 : 0,
  estado_real: estadoReal === 'LIGADO' ? 1 : 0,
  limiar_on: limOn,
  limiar_off: limOff,
  nuvens_pct: nuvens
};
const dbMsg = { payload: [ fields, { cenario: cenario } ] };
node.status({ text: cenario + ' | ' + lux.toFixed(0) + ' lux | ' + (estadoCmd||'-') });
return [cmdMsg, null, dbMsg];   // saída 2 reservada (sem uso)

// Monta a URL da OpenWeather. A chave vem de variavel de ambiente (nao fica no flows.json)
const key = env.get('OPENWEATHER_KEY');
if (!key) { node.error('Defina a variavel de ambiente OPENWEATHER_KEY'); return null; }
const cidade = env.get('OPENWEATHER_CITY') || 'Sao Paulo,BR';
msg.url = 'https://api.openweathermap.org/data/2.5/weather?q=' + encodeURIComponent(cidade) + '&units=metric&appid=' + key;
return msg;

const d = msg.payload;
if (!d || !d.clouds || typeof d.clouds.all !== 'number') { node.warn('Resposta inesperada da OpenWeather'); return null; }
flow.set('nuvens', d.clouds.all);
node.status({ text: 'nuvens ' + d.clouds.all + '%' });
msg.payload = d.clouds.all;
return msg;
